import bankData from "@data/bank.json";
import imageData from "@data/celeb-images.json";
import type { Celeb } from "./engine";
import { slugify } from "./slug";

export interface CelebImage {
  name: string;
  file: string;
  title: string;
  author: string;
  license: string;
  licenseUrl?: string;
  sourceUrl: string;
  width: number;
  height: number;
  year?: number;
}

export interface BankCeleb extends Celeb {
  image?: CelebImage;
}

const images = imageData as Record<string, CelebImage>;

export const HAS_IMAGES = Object.keys(images).length > 0;

/**
 * The rating bank, generated by scripts/build-bank.ts: every celeb in data/celebs.json with a
 * usable image. Before any images have been fetched (fresh checkout) it holds everyone, and the
 * UI shows a name card instead of a photo.
 */
export const BANK: BankCeleb[] = bankData.celebs.map((c) => {
  const id = slugify(c.name);
  return { id, name: c.name, rating: c.rating, category: c.category, image: images[id] };
});

const byId = new Map(BANK.map((c) => [c.id, c]));

export function getCeleb(id: string): BankCeleb | undefined {
  return byId.get(id);
}

/** Credits for every photo the app can show. */
export function imageCredits(): CelebImage[] {
  return BANK.flatMap((c) => (c.image ? [c.image] : [])).sort((a, b) => a.name.localeCompare(b.name));
}
